#include <stdio.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int dp[7], next[7];
    for (int i = 0; i <= 6; ++i) dp[i] = -1;

    for (int i = 0; i < n; ++i) {
        int face[7];
        for (int j = 0; j < 6; ++j) {
            int value;
            scanf("%d", &value);
            face[j] = value;
        }

        int opposite[7] = {0};
        opposite[face[0]] = face[5];
        opposite[face[5]] = face[0];
        opposite[face[1]] = face[3];
        opposite[face[3]] = face[1];
        opposite[face[2]] = face[4];
        opposite[face[4]] = face[2];

        for (int j = 0; j <= 6; ++j) next[j] = -1;

        if (i == 0) {
            for (int bottom = 1; bottom <= 6; ++bottom) {
                int top = opposite[bottom];
                int side = 0;
                for (int j = 0; j < 6; ++j) {
                    if (face[j] != bottom && face[j] != top && face[j] > side)
                        side = face[j];
                }
                next[top] = side;
            }
        } else {
            for (int previousTop = 1; previousTop <= 6; ++previousTop) {
                if (dp[previousTop] < 0) continue;
                int bottom = previousTop;
                int top = opposite[bottom];
                int side = 0;
                for (int j = 0; j < 6; ++j) {
                    if (face[j] != bottom && face[j] != top && face[j] > side)
                        side = face[j];
                }
                int total = dp[previousTop] + side;
                if (total > next[top]) next[top] = total;
            }
        }

        for (int j = 0; j <= 6; ++j) dp[j] = next[j];
    }

    int answer = 0;
    for (int top = 1; top <= 6; ++top)
        if (dp[top] > answer) answer = dp[top];

    printf("%d\n", answer);
    return 0;
}
